style.css:
@-moz-document domain("roblox.com") {
html, body {
    background-image: url("https://i.imgur.com/g4bKDg8.jpeg") !important;
    background-size: cover !important;
    background-position: center !important;
    background-attachment: fixed !important;
}

/* make Roblox containers transparent */
#container-main,
#react-root,
.content,
.container-main,
.section,
.section-content,
.games-list-container,
.game-card-container {
    background: transparent !important;
}

/* navbar */
.navbar,
.rbx-navbar {
    background: rgba(0,0,0,0.8) !important;
}

/* cards */
.card,
.game-card-container {
    background: rgba(20,20,20,0.6) !important;
    border-radius: 10px;
}
}
